mod solution;

fn main() {
    let cases = [
    (r#"start=0,0 goal=3,2"#, r#"5"#),
    (r#"start=0,0 goal=1,1"#, r#"2"#),
    (r#"
start=0,0 goal=1,1
"#, r#"2"#),
    (r#"  
start=0,0 goal=3,2
  "#, r#"5"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS a-star");
}
